-- Contexto
-- Imagina que tenemos esta tabla de laboratorio:
-- CREATE TABLE categories (
--     id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
--     name TEXT,
--     is_active BOOLEAN,
--     created_on DATE
-- );


-- Y estos registros iniciales:
-- id	name	is_active	created_on
-- 1	Alimentación	TRUE	2026-10-20
-- 2	Transporte	TRUE	2026-10-20
-- 3	Entretenimiento	FALSE	2026-10-21
-- 4	Salario	TRUE	2026-10-21
-- 5	Temporal	FALSE	2026-10-22

-- Este examen es hipotético. No ejecutes las operaciones sobre tu base de datos real; escribe las consultas como si cada pregunta comenzara con los datos iniciales de la tabla.
-- Parte 1 — SQL práctico
-- Pregunta 1 — INSERT múltiple

-- Necesitamos registrar dos nuevas categorías mediante una única sentencia SQL.
-- name	is_active	created_on
-- Salud	TRUE	2026-10-22
-- Educación	TRUE	2026-10-22

-- Requisitos: no proporcionar el id manualmente y utilizar RETURNING para obtener los identificadores y nombres insertados.

-- Pregunta 2 — UPDATE

-- El equipo de finanzas solicita modificar la categoría Entretenimiento, con id = 3.

-- Debes cambiar su nombre a Ocio y activarla. Utiliza una única sentencia UPDATE y devuelve mediante RETURNING el identificador, el nombre y el estado actualizado.

-- Pregunta 3 — DELETE

-- Necesitamos eliminar la categoría temporal con id = 5.

-- Escribe primero una consulta SELECT para verificar el registro y después una sentencia DELETE que elimine únicamente esa categoría y devuelva su identificador y nombre.
-- Parte 2 — Debugging y seguridad
-- Pregunta 4 — Detectar una operación peligrosa

-- Un desarrollador quiere desactivar exclusivamente la categoría Salario, pero escribe:
-- UPDATE categories
-- SET is_active = FALSE;


-- Explica qué problema tiene, cuáles serían sus consecuencias y escribe la consulta corregida utilizando los datos iniciales.

-- Pregunta 5 — Interpretación de resultados

-- Analiza esta consulta:
-- DELETE FROM categories
-- WHERE id = 999
-- RETURNING id, name;


-- El identificador 999 no existe.

-- Responde: ¿PostgreSQL produce un error? ¿Qué información devolvería RETURNING? ¿Qué significa la respuesta DELETE 0?
-- Parte 3 — Decisiones profesionales
-- Pregunta 6 — Diseño y seguridad

-- Estamos construyendo una aplicación de finanzas personales.

-- Una categoría llamada Alimentación tiene 200 transacciones históricas asociadas. El usuario ya no quiere utilizar esa categoría para registrar nuevos movimientos.

-- Un desarrollador propone eliminarla mediante:
-- DELETE FROM categories
-- WHERE id = 1;


-- ¿Consideras que es una buena decisión? Explica qué riesgos existen y propón una alternativa utilizando SQL. Ten en cuenta que todavía no hemos configurado Foreign Keys en nuestra tabla de laboratorio.

--1
insert into categories(name, is_active, created_on) 
values
('Salud', TRUE, '2026-10-22'),
('Educación', TRUE, '2026-10-22')
returning id,name;
--2
UPDATE categories set name = 'Ocio', is_active = TRUE where id =3 returning name, is_active, created_on;
--3
select id, name from categories where id=5;
delete from categories where id = 5 returning id, name;
--4
el problema es que no esta especificando que fila quiere hacer update, va a cambiarle el estado de is_active a todas las filas
UPDATE categories
SET is_active = FALSE where id=4;
--5
no se produce error va a devolver delete 0, es decir que no se elimino ni modifico ninguna linea
--6
no considero buena decision, el riesgo es la perdida de informacion, es mejor desactivar alimentacion con un update y cambiando is_active a false
update categories set is_active = FALSE where id = 1 returning name, id;